/** Logical OPTIONAL evaluations must survive replay without conflating equal correlated input occurrences. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeOptionalEvaluationIdentityTest {

	private static final String EX = "urn:optional-identity:";
	private static final String PREFIX = "PREFIX ex: <" + EX + ">\n";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String PACKED_FLAG = "rdf4j.lmdb.packedFtree.algebra.enabled";
	private static final String JANINO_FLAG = "rdf4j.lmdb.janinoCodegen.enabled";
	private static final String INTERPRETER_FLAG = "rdf4j.lmdb.kernelInterpreter.enabled";
	private static final String FRESH_URI = EX + "unspecified";
	private static final String STABLE_URI = EX + "deterministic";
	private static final String INDEPENDENT_QUERY = PREFIX + "SELECT ?s ?token WHERE { "
			+ "?s ex:driver ?driver . OPTIONAL { SELECT ?token WHERE { "
			+ "ex:seed ex:value ?arg . BIND(ex:unspecified(?arg) AS ?token) } } }";

	@TempDir
	File dataDir;

	private final Map<String, String> previousProperties = new LinkedHashMap<>();
	private final FreshFunction fresh = new FreshFunction();
	private final StableFunction stable = new StableFunction();
	private Function previousFresh;
	private Function previousStable;
	private SailRepository repository;

	@BeforeEach
	void setUp() {
		for (String property : List.of(NATIVE_FLAG, PACKED_FLAG, JANINO_FLAG, INTERPRETER_FLAG)) {
			previousProperties.put(property, System.getProperty(property));
			System.setProperty(property, property.equals(NATIVE_FLAG) ? "true" : "false");
		}
		FunctionRegistry functions = FunctionRegistry.getInstance();
		previousFresh = functions.get(FRESH_URI).orElse(null);
		previousStable = functions.get(STABLE_URI).orElse(null);
		functions.add(fresh);
		functions.add(stable);
		LmdbStore store = new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true));
		store.setExperimentalQueryOptimizations(false);
		repository = new SailRepository(store);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			connection.add(vf.createIRI(EX, "leftA"), vf.createIRI(EX, "driver"), vf.createLiteral(1));
			connection.add(vf.createIRI(EX, "leftB"), vf.createIRI(EX, "driver"), vf.createLiteral(2));
			connection.add(vf.createIRI(EX, "seed"), vf.createIRI(EX, "value"), vf.createLiteral(7));
		}
		assertThat(fresh.getDeterminism()).isEqualTo(Function.Determinism.UNSPECIFIED);
		assertThat(QueryEvaluationUtility.isRepeatable(fresh, QueryExecutionPolicy.DEFAULT))
				.as("the existing generic default-policy classification must remain unchanged")
				.isTrue();
	}

	@AfterEach
	void tearDown() {
		try {
			if (repository != null) {
				repository.shutDown();
			}
		} finally {
			FunctionRegistry functions = FunctionRegistry.getInstance();
			functions.remove(fresh);
			functions.remove(stable);
			if (previousFresh != null) {
				functions.add(previousFresh);
			}
			if (previousStable != null) {
				functions.add(previousStable);
			}
			previousProperties.forEach((property, value) -> {
				if (value == null) {
					System.clearProperty(property);
				} else {
					System.setProperty(property, value);
				}
			});
		}
	}

	@Test
	void independentSelectReplaysOneFreshResultAcrossLeftRows() {
		List<ResultRow> expected = List.of(row("leftA", "fresh/1"), row("leftB", "fresh/1"));
		Observation generic = observe(INDEPENDENT_QUERY, false, fresh);
		assertThat(generic.rows()).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(generic.calls()).isEqualTo(1);
		assertNativeRoute(INDEPENDENT_QUERY, "NativeSubquery");
		Observation nativeResult = observe(INDEPENDENT_QUERY, true, fresh);
		assertThat(nativeResult.rows()).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(nativeResult.calls()).as("left-row fanout replays one logical independent evaluation")
				.isEqualTo(1);
	}

	@Test
	void repeatedEvaluationOfPreparedQueryGetsAFreshIndependentResult() {
		assertNativeRoute(INDEPENDENT_QUERY, "NativeSubquery");
		fresh.calls.set(0);
		System.setProperty(NATIVE_FLAG, "true");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = nativeQuery(connection, INDEPENDENT_QUERY);
			assertThat(rows(prepared)).containsExactlyInAnyOrder(row("leftA", "fresh/1"), row("leftB", "fresh/1"));
			assertThat(rows(prepared)).containsExactlyInAnyOrder(row("leftA", "fresh/2"), row("leftB", "fresh/2"));
			assertThat(fresh.calls).as("separate evaluate calls must own separate independent RHS results").hasValue(2);
		}
	}

	@Test
	void unspecifiedFunctionCannotReuseAcrossDuplicateCorrelatedInputs() {
		String query = correlatedQuery("unspecified");
		List<ResultRow> expected = List.of(row("seed", "fresh/1"), row("seed", "fresh/2"));
		Observation generic = observe(query, false, fresh);
		assertThat(generic.rows()).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(generic.calls()).isEqualTo(2);
		assertNativeRoute(query);
		Observation nativeResult = observe(query, true, fresh);
		assertThat(nativeResult.rows()).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(nativeResult.calls()).as("UNSPECIFIED supplies no affirmative OPTIONAL cross-evaluation proof")
				.isEqualTo(2);
	}

	@Test
	void duplicateLateralOccurrencesOwnSeparateOptionalSelectEvaluations() {
		String query = PREFIX + "SELECT ?s ?token WHERE { VALUES ?s { ex:seed ex:seed } "
				+ "LATERAL { OPTIONAL { SELECT ?s ?token WHERE { "
				+ "?s ex:value ?arg . BIND(ex:unspecified(?arg) AS ?token) } } } }";
		List<ResultRow> expected = List.of(row("seed", "fresh/1"), row("seed", "fresh/2"));
		Observation generic = observe(query, false, fresh);
		assertThat(generic.rows()).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(generic.calls()).isEqualTo(2);
		assertGenericScopeFallback(query);
		Observation nativeResult = observe(query, true, fresh);
		assertThat(nativeResult.rows()).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(nativeResult.calls()).as("equal LATERAL inputs are still two logical RHS occurrences")
				.isEqualTo(2);
	}

	@Test
	void duplicateExistsOccurrencesOwnSeparateOptionalSelectEvaluations() {
		String query = PREFIX + "SELECT ?s ?token WHERE { VALUES ?s { ex:seed ex:seed } "
				+ "FILTER EXISTS { OPTIONAL { SELECT ?s ?token WHERE { "
				+ "?s ex:value ?arg . BIND(ex:unspecified(?arg) AS ?token) } } FILTER(BOUND(?token)) } }";
		List<ResultRow> expected = List.of(new ResultRow(EX + "seed", null), new ResultRow(EX + "seed", null));
		Observation generic = observe(query, false, fresh);
		assertThat(generic.rows()).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(generic.calls()).isEqualTo(2);
		assertGenericScopeFallback(query);
		Observation nativeResult = observe(query, true, fresh);
		assertThat(nativeResult.rows()).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(nativeResult.calls()).as("equal EXISTS inputs are distinct logical occurrences").isEqualTo(2);
	}

	@Test
	void deterministicFunctionCanReuseAcrossDuplicateCorrelatedInputs() {
		String query = correlatedQuery("deterministic");
		List<ResultRow> expected = List.of(row("seed", "stable/7"), row("seed", "stable/7"));
		assertThat(observe(query, false, stable).rows()).containsExactlyInAnyOrderElementsOf(expected);
		assertNativeRoute(query);
		Observation nativeResult = observe(query, true, stable);
		assertThat(nativeResult.rows()).containsExactlyInAnyOrderElementsOf(expected);
		// This counter is test instrumentation, not a query-visible function effect. The declared contract
		// permits eliding calls; this assertion checks that the eligible OPTIONAL cache actually does so.
		assertThat(nativeResult.calls()).as("an affirmative deterministic proof permits keyed RHS reuse")
				.isEqualTo(1);
	}

	@Test
	void nestedMinusDoesNotReceiveTheOptionalLeftMapping() {
		String query = PREFIX + "SELECT ?s ?token WHERE { VALUES ?s { ex:leftA ex:leftB } "
				+ "OPTIONAL { { VALUES (?y ?token) { (ex:ya ex:tokenA) (ex:yb ex:tokenB) } } "
				+ "MINUS { VALUES (?y ?s) { (ex:ya ex:leftA) (ex:yb ex:leftB) } } } }";
		List<ResultRow> expected = List.of(new ResultRow(EX + "leftA", null), new ResultRow(EX + "leftB", null));
		assertThat(observe(query, false, fresh).rows()).containsExactlyInAnyOrderElementsOf(expected);
		assertNativeRoute(query);
		assertThat(observe(query, true, fresh).rows()).containsExactlyInAnyOrderElementsOf(expected);
	}

	private Observation observe(String query, boolean nativeExecution, CountingFunction function) {
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeExecution));
		function.calls.set(0);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = nativeExecution ? nativeQuery(connection, query)
					: (SailTupleQuery) connection.prepareTupleQuery(query);
			List<ResultRow> result = rows(prepared);
			return new Observation(result, function.calls.get());
		}
	}

	private void assertNativeRoute(String query, String... requiredDetails) {
		System.setProperty(NATIVE_FLAG, "true");
		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		long islandsBefore = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			GenericPlanNode plan = nativeQuery(connection, query).explain(Explanation.Level.Telemetry)
					.toGenericPlanNode();
			List<String> paths = new ArrayList<>();
			collectPaths(plan, paths);
			assertThat(paths).as("actual semantic-native execution: %s", plan)
					.contains("nestedLoop")
					.noneMatch(path -> path.startsWith("genericFallback"));
			assertThat(plan.toString()).contains("NativeRows");
			if (requiredDetails.length != 0) {
				assertThat(plan.toString()).contains(requiredDetails);
			}
		}
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get()).isEqualTo(hostedBefore);
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(islandsBefore);
		// Telemetry evaluates the query. observe() resets its private test counter afterwards so these
		// diagnostic calls never enter a measured count or decide the expected fresh term.
	}

	private void assertGenericScopeFallback(String query) {
		System.setProperty(NATIVE_FLAG, "true");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			GenericPlanNode plan = nativeQuery(connection, query).explain(Explanation.Level.Telemetry)
					.toGenericPlanNode();
			List<String> paths = new ArrayList<>();
			collectPaths(plan, paths);
			assertThat(plan.toString()).contains("genericHostedRoot", "optional-scope-unproven");
			assertThat(paths).as("unproven occurrence ownership cannot execute a native candidate")
					.noneMatch(path -> path.contains("nestedLoop"));
		}
	}

	private static SailTupleQuery nativeQuery(SailRepositoryConnection connection, String query) {
		SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
		prepared.setForcedLmdbExecutionStrategy("nestedLoop");
		return prepared;
	}

	private static List<ResultRow> rows(SailTupleQuery query) {
		return QueryResults.asList(query.evaluate())
				.stream()
				.map(bindings -> new ResultRow(value(bindings, "s"), value(bindings, "token")))
				.toList();
	}

	private static String value(BindingSet bindings, String name) {
		Value value = bindings.getValue(name);
		return value == null ? null : value.stringValue();
	}

	private static void collectPaths(GenericPlanNode node, List<String> paths) {
		String path = node.getStringMetricActual("nativeExecutionPath");
		if (path != null) {
			for (String part : path.split("\\|")) {
				paths.add(part.trim());
			}
		}
		if (node.getPlans() != null) {
			node.getPlans().forEach(child -> collectPaths(child, paths));
		}
	}

	private static String correlatedQuery(String function) {
		return PREFIX + "SELECT ?s ?token WHERE { VALUES ?s { ex:seed ex:seed } "
				+ "OPTIONAL { ?s ex:value ?arg . BIND(ex:" + function + "(?arg) AS ?token) } }";
	}

	private static ResultRow row(String subject, String token) {
		return new ResultRow(EX + subject, EX + token);
	}

	private record ResultRow(String subject, String token) {
	}

	private record Observation(List<ResultRow> rows, int calls) {
	}

	private abstract static class CountingFunction implements Function {
		final AtomicInteger calls = new AtomicInteger();

		final int record(Value[] arguments) throws ValueExprEvaluationException {
			if (arguments.length != 1) {
				throw new ValueExprEvaluationException("Expected one store-bound argument");
			}
			return calls.incrementAndGet();
		}
	}

	private static final class FreshFunction extends CountingFunction {
		@Override
		public String getURI() {
			return FRESH_URI;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... arguments) throws ValueExprEvaluationException {
			return valueFactory.createIRI(EX + "fresh/" + record(arguments));
		}
	}

	private static final class StableFunction extends CountingFunction {
		@Override
		public String getURI() {
			return STABLE_URI;
		}

		@Override
		public Determinism getDeterminism() {
			return Determinism.DETERMINISTIC;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... arguments) throws ValueExprEvaluationException {
			record(arguments);
			return valueFactory.createIRI(EX + "stable/" + arguments[0].stringValue());
		}
	}
}
